static int prompt_tile_limit(int type, int cc, int matrices, int rows, int stock_limit) {
    static const bool enabled = []() {
        const char *value = std::getenv("IRONMULE_LAB_MMQ_TILE");
        return value && std::strcmp(value, "96") == 0;
    }();
    if (enabled && type == GGML_TYPE_Q4_K && cc == GGML_CUDA_CC_ADA_LOVELACE &&
        matrices == 1 && rows >= 384 && rows <= 512) {
        return std::min(96, stock_limit);
    }
    return stock_limit;
}
